mapper.select:
SELECT * FROM app_info

    deleted = false

        AND appName LIKE CONCAT('%', #{appName}, '%')


        AND version = #{version}


        AND buildNumber = #{buildNumber}


        AND isBeta = #{isBeta}


ORDER BY createTime DESC

mapper.update:
UPDATE app_info
appName = #{appName}, packageName = #{packageName}, version = #{version}, buildNumber = #{buildNumber}, features = #{features}, isBeta = #{isBeta}, path = #{path}, downloadTimes = #{downloadTimes}, size = #{size}, deleted = #{deleted}, showUpdatePopup = #{showUpdatePopup}, forceUpdate = #{forceUpdate},
WHERE id = #{id}

UPDATE app_info
SET downloadTimes = downloadTimes + 1
WHERE id = #{id}

mapper.select:
SELECT COUNT(1) > 0 
FROM app_info 
WHERE packageName = #{packageName} 
AND version = #{version} 
AND (deleted IS NULL OR deleted = false)

    AND id != #{excludeId}
